<?php require 'config.php';require_user();$s=$pdo->prepare('SELECT p.*,d.name destination FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN destinations d ON d.id=b.destination_id WHERE p.user_id=? ORDER BY p.created_at DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll();$page_title='My payments';require 'partials/header.php';?><section class="section"><span class="eyebrow">PAYMENT HISTORY</span><h2>My payments</h2><?php if(!$rows):?><div class="empty">No payment submissions yet.</div><?php else:?><div class="table-wrap"><table><tr><th>Destination</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th>Date</th></tr><?php foreach($rows as $p):?><tr><td><?=e($p['destination'])?></td><td>₹<?=number_format((float)$p['amount'],2)?></td><td><?=e($p['method'])?></td><td><?=e($p['transaction_ref'])?></td><td><span class="status <?=e($p['status'])?>"><?=e($p['status'])?></span></td><td><?=e($p['created_at'])?></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php require 'partials/footer.php';?>
